/**
 * Collect the licence text of every dependency bundled into dist/.
 *
 * The published package declares no runtime dependencies because Vite and
 * esbuild inline everything. That is convenient, but redistributing MIT, ISC
 * and BSD-licensed code in a bundle still carries their notice clauses -- all
 * three condition redistribution on retaining the copyright notice. Shipping
 * dist/ without them is a licence breach, so this file is generated as part of
 * the build and included in the tarball.
 */
import { readdir, readFile, writeFile, stat } from 'node:fs/promises'
import { join } from 'node:path'

const ROOT = new URL('..', import.meta.url).pathname
const MODULES = join(ROOT, 'node_modules')
const LICENSE_FILES = ['LICENSE', 'LICENSE.md', 'LICENSE.txt', 'LICENCE', 'LICENCE.md', 'license', 'LICENSE-MIT']

/** Packages whose code actually ends up in the shipped bundle. */
const BUNDLED_ROOTS = ['react', 'react-dom', '@xyflow/react', '@dagrejs/dagre']

async function readJson(path) {
  try {
    return JSON.parse(await readFile(path, 'utf8'))
  } catch {
    return null
  }
}

async function findLicenseText(dir) {
  let entries
  try {
    entries = await readdir(dir)
  } catch {
    return null
  }
  for (const candidate of LICENSE_FILES) {
    const match = entries.find((entry) => entry.toLowerCase() === candidate.toLowerCase())
    if (!match) continue
    const path = join(dir, match)
    if ((await stat(path)).isFile()) return (await readFile(path, 'utf8')).trim()
  }
  return null
}

/** Walk the real dependency graph of the packages we bundle. */
async function collect() {
  const seen = new Map()
  const queue = [...BUNDLED_ROOTS]

  while (queue.length > 0) {
    const name = queue.shift()
    if (seen.has(name)) continue

    const dir = join(MODULES, name)
    const pkg = await readJson(join(dir, 'package.json'))
    if (!pkg) continue

    seen.set(name, {
      name,
      version: pkg.version,
      license: pkg.license ?? pkg.licenses?.[0]?.type ?? 'UNKNOWN',
      homepage: pkg.homepage ?? pkg.repository?.url ?? '',
      text: await findLicenseText(dir),
    })

    for (const dependency of Object.keys(pkg.dependencies ?? {})) queue.push(dependency)
  }

  return [...seen.values()].sort((a, b) => a.name.localeCompare(b.name))
}

const packages = await collect()
const missing = packages.filter((entry) => !entry.text)

const body = [
  '# Third-party notices',
  '',
  'lgview is distributed as a pre-bundled package: the JavaScript in `dist/`',
  'contains code from the projects below, compiled in. Their licences are',
  'reproduced here in full, as those licences require.',
  '',
  'This file is generated by `scripts/third-party-notices.mjs` during the build.',
  'Do not edit it by hand.',
  '',
  '## Summary',
  '',
  '| package | version | licence |',
  '| --- | --- | --- |',
  ...packages.map((entry) => `| ${entry.name} | ${entry.version} | ${entry.license} |`),
  '',
  ...packages.flatMap((entry) => [
    '---',
    '',
    `## ${entry.name} ${entry.version}`,
    '',
    entry.homepage ? `${entry.homepage}` : '',
    '',
    '```',
    entry.text ?? `${entry.license} — licence text not found in the published package.`,
    '```',
    '',
  ]),
].join('\n')

await writeFile(join(ROOT, 'THIRD-PARTY-NOTICES.md'), `${body}\n`)

console.log(`third-party notices: ${packages.length} packages`)
if (missing.length > 0) {
  console.warn(`  warning: no licence text found for ${missing.map((entry) => entry.name).join(', ')}`)
}
